"""Small collaboration-network analysis: build a graph, tag people, look at structure."""
import networkx as nx


def build_graph(edges):
    """edges: iterable of (a, b, weight)."""
    G = nx.Graph(name="team")
    for a, b, weight in edges:
        G.add_edge(a, b, weight=weight)
    return G


def tag_roles(G, roles):
    nx.set_node_attributes(G, roles, "role")
    return G


def role_of(G, person):
    return G.node[person].get("role", "unknown")


def weighted_edges(G):
    return sorted((a, b, d["weight"]) for a, b, d in G.edges(data=True))


def describe(G):
    return nx.info(G)


def adjacency(G, order):
    return nx.to_numpy_matrix(G, nodelist=order, weight="weight")


def two_hop_weights(G, order):
    A = adjacency(G, order)
    return (A * A).tolist()


def strengths(G, order):
    return adjacency(G, order).sum(axis=1).A1.tolist()


def self_loop_count(G):
    return len(list(G.selfloop_edges()))


def largest_component(G):
    parts = nx.connected_component_subgraphs(G)
    return max(parts, key=lambda g: g.number_of_nodes())


def influence(G):
    return {n: round(v, 4) for n, v in nx.pagerank(G, weight="weight").items()}


def save_graph(G, path):
    nx.write_gpickle(G, path)


def load_graph(path):
    return nx.read_gpickle(path)

